/// Generated by bezier_approx: 1-D Bézier, degree 8, on [0, 1].
/// Trained on 100 samples, training RMS residual 1.941e-6.
/// Plain Rust: no crate, no allocation, works in `no_std`. Inputs outside the box are clamped to it.
/// Per call: 9 multiplications, 9 additions, 2 comparisons; no divisions or loops.
/// Stores 9 coefficients (72 bytes).
/// Largest difference from the fitted model at 1000 test inputs: 7.8e-16.
#[rustfmt::skip]
#[allow(non_snake_case, clippy::unreadable_literal, clippy::approx_constant)]
pub fn exp_cos(x: [f64; 1]) -> f64 {
    // Map each input from the box to [-1, 1].
    let u0 = ((x[0] - 0.5) * 2.0).clamp(-1.0, 1.0);
    -0.25240641858236296 + u0 * (-0.9768508262431226 + u0 * (1.0247822348080218 + u0 * (0.3506531584442809 + u0 * (-0.4505380705116424 + u0 * (0.014355347494924127 + u0 * (0.06120553925449797 + u0 * (-0.008400895147948582 + u0 * -0.0032788361861861596)))))))
}
/// Generated by bezier_approx: 2-D Bézier, degree 4, on [0, 1] × [0, 1].
/// Trained on 2000 samples, training RMS residual 9.966e-3.
/// Plain Rust: no crate, no allocation, works in `no_std`. Inputs outside the box are clamped to it.
/// Per call: 26 multiplications, 26 additions, 4 comparisons; no divisions or loops.
/// Stores 25 coefficients (200 bytes).
/// Largest difference from the fitted model at 1000 test inputs: 5.6e-16.
#[rustfmt::skip]
#[allow(non_snake_case, clippy::unreadable_literal, clippy::approx_constant)]
pub fn surface(x: [f64; 2]) -> f64 {
    // Map each input from the box to [-1, 1].
    let u0 = ((x[0] - 0.5) * 2.0).clamp(-1.0, 1.0);
    let u1 = ((x[1] - 0.5) * 2.0).clamp(-1.0, 1.0);
    // p1_j: the factor of u1^j, a polynomial in u0.
    let p1_0 = 0.6891269866986657 + u0 * (0.4687918883577295 + u0 * (-0.2974922358580125 + u0 * (-0.0620350874507979 + u0 * 0.013389379168169867)));
    let p1_1 = -0.3553393451742756 + u0 * (-0.20063221591874297 + u0 * (0.22742928012432997 + u0 * (0.04604424636670852 + u0 * -0.032486310250223006)));
    let p1_2 = -0.1714689046758277 + u0 * (-0.10321895679572632 + u0 * (0.07985449294199508 + u0 * (0.014422439150150958 + u0 * -0.0008498965577887411)));
    let p1_3 = 0.04077838432693114 + u0 * (0.026465872835080992 + u0 * (-0.04028231503190988 + u0 * (-0.013918973421081466 + u0 * 0.02095257985806654)));
    let p1_4 = 0.007501158309667235 + u0 * (-0.0025640127438414963 + u0 * (-0.009236473107435965 + u0 * (-0.001883096706145779 + u0 * 0.0013286135440351927)));
    p1_0 + u1 * (p1_1 + u1 * (p1_2 + u1 * (p1_3 + u1 * p1_4)))
}
/// Generated by bezier_approx: 1-D spline, degree 3, 8 segments, on [0, 1].
/// Trained on 200 samples, training RMS residual 9.382e-4.
/// Plain Rust: no crate, no allocation, works in `no_std`. Inputs outside the box are clamped to it.
/// Per call: 5 multiplications, 6 additions, 3 comparisons, 1 float-to-integer conversion and a table lookup; no divisions or loops.
/// Stores 32 coefficients (256 bytes).
/// Largest difference from the fitted model at 1000 test inputs: 2.2e-16.
#[rustfmt::skip]
#[allow(non_snake_case, clippy::unreadable_literal, clippy::approx_constant)]
pub fn bend(x: [f64; 1]) -> f64 {
    // One row per piece: its polynomial in u0, constant term first.
    static C: [[f64; 4]; 8] = [
        [0.0004210246592615932, -0.0014700397975014661, -0.001446792531146371, 0.0014513070824902366], // x0 in [0, 0.125]
        [0.0007015837576811698, 0.00235053154205419, -0.0005468935619466493, -0.0011513407594236627], // x0 in [0.125, 0.25]
        [-0.001466652939343603, -6.613019268812519e-5, 0.0061320635076396075, 0.0033776597826190814], // x0 in [0.25, 0.375]
        [0.04430781670164083, 0.0480656344338481, 0.009469615407902912, -0.002265142482531314], // x0 in [0.375, 0.5]
        [0.16181744772102602, 0.06362550741606765, 0.0007418816536987026, -0.0006441021022034234], // x0 in [0.5, 0.625]
        [0.2878441313961965, 0.0617466859420247, -0.0002398538219185245, 0.0003168569436643471], // x0 in [0.625, 0.75]
        [0.41238052555666643, 0.06299230002266226, 6.403388440708035e-5, -0.00021556104155580694], // x0 in [0.75, 0.875]
        [0.5374089459205057, 0.062198222401619596, 0.0003071869750708722, 0.0002966120717770998], // x0 in [0.875, 1]
    ];
    // Find the piece along each axis, and the position in it, u in [-1, 1].
    let t0 = ((x[0] - 0.0) * 8.0).clamp(0.0, 8.0);
    let s0 = (t0 as usize).min(7);
    let u0 = 2.0 * (t0 - s0 as f64) - 1.0;
    let c = &C[s0];
    c[0] + u0 * (c[1] + u0 * (c[2] + u0 * c[3]))
}

fn main() {
    // Inference: no allocation, no training code involved. The standalone functions
    // compute the same values in a different way, so they agree to rounding error.
    for x in [0.0f64, 0.25, 0.5, 0.75, 1.0] {
        let truth = (-x).exp() * (4.0 * x).cos();
        let (a, b) = (EXP_COS.eval([x]), exp_cos([x]));
        assert!((a - b).abs() < 1e-14);
        println!("EXP_COS({x:.2}) = {a:+.7}   exp_cos = {b:+.7}   (true {truth:+.7})");
    }
    for p in [[0.2f64, 0.4], [0.6, 0.1], [0.9, 0.9]] {
        let truth = (2.0 * p[0]).sin() * (1.5 * p[1]).cos() + 0.3 * p[0] * p[1];
        let (a, b) = (SURFACE.eval(p), surface(p));
        assert!((a - b).abs() < 1e-14);
        println!("SURFACE({p:?}) = {a:+.5}   surface = {b:+.5}   (true {truth:+.5})");
    }
    for x in [0.0f64, 0.3, 0.4, 0.5, 1.0] {
        let truth = (1.0 + (40.0 * (x - 0.4)).exp()).ln() / 40.0;
        let (a, b) = (BEND.eval([x]), bend([x]));
        assert!((a - b).abs() < 1e-14);
        println!("BEND({x:.2}) = {a:+.6}   bend = {b:+.6}   (true {truth:+.6})");
    }
}
